# region: emit
def emit(raw):
    return [len(tok.strip()) for tok in raw if tok.strip()]

# region: digest
def digest(xs, limit=20):
    return [v if v <= limit else limit for v in xs]

# region: intake
def intake(xs, cut=8):
    lo = [v for v in xs if v < cut]
    hi = [v for v in xs if v >= cut]
    return {'n': len(xs) - 1, 'lo': len(lo), 'hi': len(hi)}

# region: render
def render(summary, bar=4):
    out = dict(summary)
    n = summary.get('n', 0)
    out['ratio'] = round(n / bar, 3) if bar else 0.0
    return out

# region: run
def run(raw):
    return render(intake(digest(emit(raw))))

