        self.assertEqual(run([' 5 ', '-2', '8']), {'n': 3, 'lo': 3, 'hi': 0, 'ratio': 0.75})
    def test_case_03(self):
        self.assertEqual(run(['4:2', '9:1', 'bad']), {'n': 3, 'lo': 3, 'hi': 0, 'ratio': 0.75})
    def test_case_04(self):
        self.assertEqual(run(['12', '12', '1']), {'n': 3, 'lo': 3, 'hi': 0, 'ratio': 0.75})
    def test_case_05(self):
        self.assertEqual(run(['0']), {'n': 1, 'lo': 1, 'hi': 0, 'ratio': 0.25})
    def test_case_06(self):
        self.assertEqual(run(['6', '6', '6', '6']), {'n': 4, 'lo': 4, 'hi': 0, 'ratio': 1.0})
